export interface AppError {
  id: string;
  timestamp: string;
  title: string;
  message: string;
  type: 'APP' | 'NETWORK';
  stack?: string;
  raw?: unknown;
}

@Injectable({
  providedIn: 'root'
})
export class GlobalErrorHandlerService implements ErrorHandler {
  private zone = inject(NgZone);

  // Public signal for UI
  activeError = signal<AppError | null>(null);

  // List of harmless errors to ignore
  private readonly IGNORED_ERRORS = [
    'ResizeObserver loop limit exceeded',
    'ResizeObserver loop completed with undelivered notifications'
  ];

  handleError(error: unknown): void {
    // 1. Filter out noise
    if (this.isIgnored(error)) {
      console.warn('GlobalErrorHandler: Ignored non-critical UI error:', error);
      return;
    }

    const appError = this.parseError(error);

    // 2. DX: Beautiful Console Log
    this.logToConsole(appError);

    // 3. UX: Update UI (ensure it runs in zone to trigger change detection)
    this.zone.run(() => {
      this.activeError.set(appError);
    });
  }

  clearError() {
    this.activeError.set(null);
  }

  private isIgnored(error: unknown): boolean {
    const msg = this.extractMessage(error);
    return this.IGNORED_ERRORS.some(ignore => msg.includes(ignore));
  }

  private extractMessage(error: unknown): string {
    if (error instanceof Error) return error.message;
    if (typeof error === 'string') return error;
    if (typeof error === 'object' && error !== null && 'message' in error) return String((error as {message: unknown}).message);
    return '';
  }

  private parseError(error: unknown): AppError {
    const id = crypto.randomUUID().slice(0, 8);
    const timestamp = new Date().toLocaleTimeString();

    let title = 'Системная ошибка';
    let message = 'Произошла непредвиденная ошибка';
    let type: 'APP' | 'NETWORK' = 'APP';
    let stack = '';

    if (error instanceof HttpErrorResponse) {
      const httpError = error as HttpErrorResponse;
      type = 'NETWORK';
      title = `Ошибка сети (${httpError.status})`;

      // Smart extraction: Look for backend message in the body
      const backendMsg = this.extractBackendMessage(httpError);
      message = backendMsg || httpError.message || 'Не удалось выполнить запрос к серверу';

      stack = httpError.url || '';
    } else if (error instanceof Error) {
      title = error.name || 'Runtime Error';
      message = error.message;
      stack = error.stack || '';
    } else if (typeof error === 'string') {
        message = error;
    } else if (typeof error === 'object' && error !== null) {
        // Fallback for objects that look like errors
        message = this.extractMessage(error) || JSON.stringify(error);
    }

    return { id, timestamp, title, message, type, stack, raw: error };
  }

  private extractBackendMessage(error: HttpErrorResponse): string | null {
    // Backend often sends JSON: { error: "User not found" } or { message: "..." }
    if (error.error) {
        if (typeof error.error === 'string') {
            return error.error;
        }
        if (typeof error.error === 'object') {
            return error.error.message || error.error.error || null;
        }
    }
    return null;
  }

  private logToConsole(err: AppError) {
    const styleTitle = 'font-weight: bold; font-size: 1.1em; padding: 4px; border-radius: 4px; color: white;';
    const bg = err.type === 'NETWORK' ? 'background: #f59e0b;' : 'background: #ef4444;'; // Orange vs Red

    console.group(`%c 🚨 ${BRANDING.name} Error [${err.id}] `, `${styleTitle} ${bg}`);
    console.log(`%c Title: `, 'color: #aaa; font-weight: bold;', err.title);
    console.log(`%c Message: `, 'color: #fff; font-weight: bold;', err.message); // White for visibility
    if (err.stack) {
        console.groupCollapsed('%c Stack Trace / Details', 'color: #60a5fa;');
        console.log(err.stack);
        console.groupEnd();
    }
    console.groupEnd();
  }
}

@Component({
  selector: 'app-global-error',
  imports: [CommonModule],
  templateUrl: './global-error.component.html'
})
export class GlobalErrorComponent {
  private errorService = inject(GlobalErrorHandlerService);

  error = this.errorService.activeError;
  showDetails = signal(false);

  close() {
    this.errorService.clearError();
    this.showDetails.set(false);
  }

  toggleDetails() {
    this.showDetails.update(v => !v);
  }

  copyReport() {
    const err = this.error();
    if (!err) return;

    const report = JSON.stringify({
        id: err.id,
        time: err.timestamp,
        title: err.title,
        message: err.message,
        stack: err.stack
    }, null, 2);

    navigator.clipboard.writeText(report).then(() => {
        alert('Отчет скопирован в буфер обмена');
    });
  }
}
